/**
 * Self-contained HTML rendering of `atl.report/v1` (04 §9.4): inline CSS and SVG, no scripts, no external fonts or
 * images; `@media print` for A4. The share copy (§9.5) is the same renderer over a redacted report with a banner.
 * Every value is escaped; the chart SVG is generated by `charts.ts` from numbers only.
 */
import { escapeXml } from './charts.js';
import type { Report } from './report.js';

const esc = (v: unknown): string => escapeXml(v === undefined || v === null ? '—' : typeof v === 'string' ? v : JSON.stringify(v));

const STATE_LABEL: Record<string, string> = {
  done: '已达成',
  done_manual: '已达成（含手动）',
  drifted: '漂移',
  failed: '未通过',
  error: '检测器出错',
  needs_manual: '待手动确认',
  verifying: '核验中',
  available: '可开始',
  locked: '未解锁',
  skipped: '已跳过',
};
const ATTEMPT_LABEL: Record<string, string> = {
  completed: '已完成（全自动）',
  completed_manual: '已完成（含手动）',
  incomplete: '未完成',
  unverified: '未能核验',
  active: '进行中',
  verifying: '最终复核中',
  void: '作废',
};
const RESULT_LABEL: Record<string, string> = {
  pass: '通过',
  fail: '未通过',
  pending: '等待中',
  error: '检测器出错',
  unavailable: '无法检测',
  skipped: '不适用',
  not_run: '未检测',
  manual: '已手动确认',
  manual_evidence: '已手动确认（带证据）',
  needs_manual: '待手动确认',
};

const CSS = `
:root{--fg:#1d2330;--muted:#5b6475;--line:#d9dee7;--bg:#fff;--ok:#1b7f3a;--bad:#b42318;--warn:#9a6700}
@media (prefers-color-scheme:dark){:root{--fg:#e6e9ef;--muted:#a3acbd;--line:#2b313c;--bg:#12151b;--ok:#4cc27a;--bad:#ff7b72;--warn:#e3b341}}
body{margin:0;background:var(--bg);color:var(--fg);font:14px/1.6 system-ui,-apple-system,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}
main{max-width:960px;margin:0 auto;padding:24px 16px 48px}
h1{font-size:22px;margin:0 0 4px}h2{font-size:17px;margin:28px 0 8px;border-bottom:1px solid var(--line);padding-bottom:4px}h3{font-size:15px;margin:16px 0 6px}
.muted{color:var(--muted)}.banner{border:1px solid var(--line);border-left:4px solid var(--warn);padding:10px 12px;margin:12px 0;color:var(--muted)}
table{border-collapse:collapse;width:100%;margin:6px 0 12px}th,td{border-bottom:1px solid var(--line);padding:4px 6px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{color:var(--muted);font-weight:500}
.pass,.done{color:var(--ok)}.fail,.failed,.drifted{color:var(--bad)}.pending,.verifying,.needs_manual{color:var(--warn)}
code{font-size:12px}figure{margin:8px 0}
@media print{@page{size:A4 portrait;margin:14mm}body{background:#fff;color:#000}main{max-width:none;padding:0}tr,figure,table{break-inside:avoid}.noprint{display:none}}
`;

export interface RenderOptions {
  /** Share copies (§9.5): a banner and no manual notes. */
  share?: boolean;
  hideManualNotes?: boolean;
  includeHistory?: boolean;
}

export function renderReportHtml(r: Report, o: RenderOptions = {}): string {
  const h: string[] = [];
  h.push(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">`);
  // frame-ancestors only works as a header (browsers log an error for it in <meta>): CloudFront's atl-web-share policy sends it
  h.push(`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:">`);
  if (o.share) h.push('<meta name="robots" content="noindex, nofollow"><meta name="referrer" content="no-referrer">');
  h.push(`<title>${esc(r.lab.title)} · 实验报告</title><style>${CSS}</style></head><body><main>`);
  if (o.share) h.push('<p class="banner">这是由自托管 ATL 实验平台生成的脱敏报告副本，不是 AWS 官方认证。</p>');
  h.push(`<h1>${esc(r.lab.title)}</h1><p class="muted">实验报告 · 第 ${r.revision} 版 · 生成于 ${esc(r.generatedAt)} · 卡片版本 ${esc(r.lab.version)} · 起始变体 ${esc(r.lab.variant)}</p>`);
  // summary
  h.push('<h2>摘要</h2><table>');
  h.push(`<tr><th>结论</th><td>${esc(ATTEMPT_LABEL[r.outcome.attemptStatus] ?? r.outcome.attemptStatus)}${r.badge ? ` · 徽章“${esc(r.badge.title)}” · ${esc(r.badge.level)}（证据分 ${esc(r.badge.evidenceScore)}）${r.badge.status !== 'valid' ? ` · ${esc(r.badge.status)}` : ''}` : ''}</td></tr>`);
  h.push(`<tr><th>持有人</th><td>${esc(r.learner.displayName)}</td></tr>`);
  h.push(`<tr><th>用时</th><td>${r.timing.totalMinutes} 分钟（步骤累计 ${r.timing.activeMinutes} 分钟）</td></tr>`);
  h.push(`<tr><th>检查</th><td>自动 ${r.outcome.checks.auto} · 手动 ${r.outcome.checks.manual} · 未满足 ${r.outcome.checks.failed} · 漂移 ${r.outcome.driftEvents}</td></tr>`);
  h.push(`<tr><th>证据可信度</th><td>高 ${r.outcome.trustSummary.high} · 中 ${r.outcome.trustSummary.medium} · 低 ${r.outcome.trustSummary.low}</td></tr>`);
  h.push(`<tr><th>会话</th><td>区域 ${esc(r.session.region)} · 账号 ${esc(r.session.accountIdMasked)} · 结束原因 ${esc(r.session.endReason)}${r.session.environment.reused ? ' · 复用环境' : ''}</td></tr>`);
  h.push('</table>');
  // architecture / start profile
  h.push(`<h2>架构变化</h2><p>起始档位 <code>${esc(r.lab.startProfile.name)}</code></p><table><tr><th>起始项</th><th>类型</th><th>理由</th></tr>`);
  for (const p of r.lab.startProfile.provisions) h.push(`<tr><td>${esc(p.item)}</td><td>${esc(p.kind)}</td><td>${esc(p.reason)}</td></tr>`);
  h.push('</table>');
  // steps
  h.push('<h2>逐步证据</h2>');
  for (const s of r.steps) {
    h.push(`<h3>${esc(s.title)} <span class="${esc(s.state)}">· ${esc(STATE_LABEL[s.state] ?? s.state)}</span></h3>`);
    if (!s.checks.length) continue;
    h.push('<table><tr><th>检查</th><th>来源</th><th>结果</th><th>关键断言（期望 / 实际）</th><th>证据摘要</th></tr>');
    for (const c of s.checks) {
      const asserts = c.keyAssertions.map((a) => `${a.ok ? '✓' : '✗'} ${esc(a.label)}：${esc(a.expected)} / ${esc(a.actual)}`).join('<br>');
      const prov = c.provenance && c.provenance !== 'this-session' ? '<br><span class="muted">继承自前一会话</span>' : '';
      const late = c.ownershipConfirmedLate ? '<br><span class="muted">归属在会话结束后确认</span>' : '';
      const manual = c.manual ? `<br><span class="muted">手动确认：${esc(c.manual.observed)}${o.hideManualNotes ? '' : ` · ${esc(c.manual.note)}`}</span>` : '';
      h.push(`<tr><td>${esc(c.title)}${prov}${late}</td><td>${esc(c.source)}${c.trust && c.trust !== 'high' ? ` · ${esc(c.trust)}` : ''}</td><td class="${esc(c.effective)}">${esc(RESULT_LABEL[c.effective] ?? c.effective)}</td><td>${asserts || '—'}${manual}</td><td><code>${esc((c.evidenceDigest ?? '').slice(0, 15))}</code></td></tr>`);
    }
    h.push('</table>');
  }
  // experiments
  h.push('<h2>对比实验</h2>');
  if (!r.experiments.length) h.push('<p class="muted">本卡片没有对比实验。</p>');
  for (const e of r.experiments) {
    h.push(`<h3>${esc(e.module)} / ${esc(e.experiment)}</h3><table><tr><th>变体</th><th>角色</th><th>记录</th></tr>`);
    for (const v of e.variants) h.push(`<tr><td>${esc(v.label)}</td><td>${esc(v.role)}</td><td>${v.summary ? `${esc((v.summary as { validity?: string }).validity)} · ${esc((v.summary as { finishedAt?: string }).finishedAt)}` : '无记录'}</td></tr>`);
    h.push('</table>');
    for (const p of e.pairs) h.push(`<p>${esc(p.a)} / ${esc(p.b)}：${p.comparable ? '可比' : `不可比（${esc(p.reasons.join('；'))}）`}${p.across?.length ? ' · 跨实例类型比较' : ''}</p>`);
    for (const c of e.charts) h.push(`<figure>${c.svg}</figure>`);
  }
  // quiz
  if (r.quiz) h.push(`<h2>小测</h2><p>最好成绩 ${esc(r.quiz.bestScore)}（共 ${r.quiz.attempts} 次；只记录，不影响完成与徽章）</p>`);
  // cost
  h.push('<h2>费用</h2>');
  h.push(`<p class="muted">${esc(r.cost.notes.join(' · '))}</p>`);
  if (r.cost.quote) h.push(`<p>开始前估算：报价 <code>${esc((r.cost.quote as { quoteId?: string }).quoteId)}</code></p>`);
  if (r.cost.resources.length) {
    h.push('<table><tr><th>资源类型</th><th>名称</th><th>计费方式</th><th>时长（小时）</th></tr>');
    for (const x of r.cost.resources) h.push(`<tr><td>${esc(x.resourceType)}</td><td>${esc(x.name)}</td><td>${esc(x.billing)}</td><td>${esc(x.hours)}</td></tr>`);
    h.push('</table>');
  }
  // cleanup
  h.push(`<h2>清理</h2><p>状态：${esc(r.cleanup.status)} · 已回收 ${r.cleanup.reclaimed} 项</p>`);
  if (r.cleanup.pendingManual.length) {
    h.push('<table><tr><th>待人工处理</th><th>标识</th><th>级别</th><th>原因</th></tr>');
    for (const p of r.cleanup.pendingManual) h.push(`<tr><td>${esc(p.resourceType)}</td><td>${esc(p.id)}</td><td>${esc(p.severity)}</td><td>${esc(p.reason)}</td></tr>`);
    h.push('</table>');
  }
  for (const v of r.cleanup.verify) h.push(`<p>清理验证 ${esc(v.checkKey)}：${esc(RESULT_LABEL[v.result] ?? v.result)}</p>`);
  if (r.certificate) h.push(`<h2>证书</h2><p>证书 ${esc(r.certificate.certId)} · 验证：${esc(r.certificate.verifyUrl)}</p>`);
  // appendix
  if (o.includeHistory !== false && r.checkHistory.length) {
    h.push('<h2>附录：完整检查记录</h2><table><tr><th>时间</th><th>检查</th><th>结果</th><th>错误码</th><th>触发</th></tr>');
    for (const c of r.checkHistory) h.push(`<tr><td>${esc(c.at)}</td><td>${esc(c.checkKey)}</td><td class="${esc(c.result)}">${esc(RESULT_LABEL[c.result] ?? c.result)}</td><td>${esc(c.errorCode ?? '')}</td><td>${esc(c.trigger)}</td></tr>`);
    h.push('</table>');
  }
  h.push(`<p class="muted">内容版本 ${esc(r.lab.catalogVersion)} · 内容摘要 <code>${esc(r.lab.contentDigest)}</code> · 报告摘要 <code>${esc(r.integrity.digest)}</code>（RFC 8785）</p>`);
  h.push('<p class="muted">本报告由自托管 AWS Training Lab 实例生成，不是 AWS 官方认证。费用为估算，以官方定价与账单为准。</p>');
  if (o.share) h.push('<p class="muted">平台卸载后此链接失效。</p>');
  h.push('</main></body></html>');
  return h.join('\n');
}
